static int[] slideLeft(int[] row) {
        int n = row.length;
        int[] out = new int[n];
        int pos = 0;
        int prev = 0;
        boolean merged = false;
        for (int v : row) {
            if (v == 0) {
                continue;
            }
            if (!merged && prev == v) {
                out[pos - 1] = 2 * v;
                prev = 0;
                merged = true;
            } else {
                out[pos++] = v;
                prev = v;
            }
        }
        return out;
}

